1	/**
2	 * Checks manifest-owned Aspire literals against the scaffold SDK pin.
3	 *
4	 * Phase 1 fails only scaffold constants, CI, and root config. Phase 2 is the
5	 * complete non-archival enforcement contract and is intentionally not enabled
6	 * in CI until the S13 slice.
7	 */
8	import { SCAFFOLD_VERSIONS } from '../../../packages/cli/src/kernel/constants/scaffold/scaffold-versions.ts';
9	import { buildAspireSurfaceManifest } from '../../runs/research-aspire-13.5-adoption--0.0.7/tools/aspire-surface-manifest.ts';
10	
11	export const ASPIRE_SURFACE_MANIFEST_PATH =
12	  '.llm/runs/research-aspire-13.5-adoption--0.0.7/aspire-surface-manifest.tsv';
13	
14	export type ParityPhase = 1 | 2;
15	export type FindingStatus = 'fail' | 'deferred' | 'info';
16	export const PHASE_TWO_COMPAT_VERSION = '13.5.3';
17	
18	export interface ManifestRow {
19	  path: string;
20	  class: string;
21	  owner: string;
22	  disposition: string;
23	}
24	
25	export interface ParityFinding {
26	  path: string;
27	  class: string;
28	  owner: string;
29	  status: FindingStatus;
30	  matches: string[];
31	  reason: string;
32	}
33	
34	export interface ParityReport {
35	  gate: 'check:aspire-version-parity';
36	  phase: ParityPhase;
37	  expectedVersion: string;
38	  manifest: string;
39	  ok: boolean;
40	  counts: {
41	    checked: number;
42	    fail: number;
43	    deferred: number;
44	    info: number;
45	    skipped: number;
46	    missing: number;
47	  };
48	  findings: ParityFinding[];
49	  skipped: string[];
50	  missing: string[];
51	  manifestFresh: boolean;
52	}
53	
54	interface EvaluateOptions {
55	  rows: readonly ManifestRow[];
56	  phase: ParityPhase;
57	  expectedVersion: string;
58	  readText: (path: string) => Promise<string | null>;
59	  manifestPath?: string;
60	  manifestSource?: string;
61	  generatedManifestSource?: string;
62	  generatedManifestUnmatched?: readonly string[];
63	}
64	
